update public.cybersecurity_projects
set framework_scope = case project_code
  when 'R-01' then 'ECC 1-1-1 — استراتيجية الأمن السيبراني؛ ECC 1-1-2 — استراتيجية الأمن السيبراني؛ ECC 1-1-3 — استراتيجية الأمن السيبراني؛ ECC 1-2-1 — إدارة الأمن السيبراني؛ ECC 1-3-1 — سياسات وإجراءات الأمن السيبراني؛ ECC 1-8-1 — المراجعة والتدقيق الدوري للأمن السيبراني'
  when 'R-02' then 'ECC 2-2-1 — إدارة هويات الدخول والصلاحيات؛ ECC 2-2-2 — إدارة هويات الدخول والصلاحيات؛ ECC 2-2-3 — إدارة هويات الدخول والصلاحيات؛ ECC 2-2-4 — إدارة هويات الدخول والصلاحيات'
  when 'R-03' then 'ECC 2-5-1 — إدارة أمن الشبكات؛ ECC 2-5-2 — إدارة أمن الشبكات؛ ECC 2-5-3 — إدارة أمن الشبكات؛ ECC 2-5-4 — إدارة أمن الشبكات'
  when 'R-04' then 'ECC 2-3-1 — حماية الأنظمة ومرافق معالجة المعلومات؛ ECC 2-3-2 — حماية الأنظمة ومرافق معالجة المعلومات؛ ECC 2-3-3 — حماية الأنظمة ومرافق معالجة المعلومات؛ ECC 2-3-4 — حماية الأنظمة ومرافق معالجة المعلومات'
  when 'R-05' then 'ECC 2-12-1 — إدارة سجلات الأحداث والمراقبة للأمن السيبراني؛ ECC 2-12-2 — إدارة سجلات الأحداث والمراقبة للأمن السيبراني؛ ECC 2-13-1 — إدارة حوادث وتهديدات الأمن السيبراني؛ ECC 2-13-2 — إدارة حوادث وتهديدات الأمن السيبراني'
  when 'R-06' then 'ECC 2-10-1 — إدارة الثغرات؛ ECC 2-10-2 — إدارة الثغرات؛ ECC 2-11-1 — اختبار الاختراق؛ ECC 2-11-2 — اختبار الاختراق'
  when 'R-07' then 'ECC 2-1-1 — إدارة الأصول؛ DCC — ضوابط تصنيف وحماية البيانات المنطبقة'
  when 'R-08' then 'CCC — ضوابط الأمن السيبراني للحوسبة السحابية المنطبقة على نطاق الخدمة'
  when 'R-09' then 'ECC — ضوابط استمرارية الأعمال والتعافي من الكوارث المنطبقة'
  when 'R-10' then 'ECC 2-4-1 — حماية البريد الإلكتروني؛ ECC 2-4-2 — حماية البريد الإلكتروني؛ ECC 2-15-1 — أمن تطبيقات الويب؛ ECC 2-15-2 — أمن تطبيقات الويب'
  when 'R-11' then 'ECC 1-7-1 — الالتزام بمعايير وأنظمة وتشريعات الأمن السيبراني؛ ECC 1-8-1 — المراجعة والتدقيق الدوري للأمن السيبراني؛ ECC 1-8-2 — المراجعة والتدقيق الدوري للأمن السيبراني؛ ECC 1-8-3 — المراجعة والتدقيق الدوري للأمن السيبراني'
end
where project_code in ('R-01','R-02','R-03','R-04','R-05','R-06','R-07','R-08','R-09','R-10','R-11');
